4. Store wrapped DEK, IV, and auth tag in blob metadata\r\n * \r\n * Download process:\r\n * 1. Download blob and read metadata\r\n * 2. Unwrap DEK using Key Vault\r\n * 3. Decrypt data locally using the unwrapped DEK\r\n */\r\nexport class EncryptedBlobStorage {\r\n  constructor(\r\n    private readonly blobServiceClient: BlobServiceClient,\r\n    private readonly keyManager: KeyManager\r\n  ) {}\r\n\r\n  /**\r\n   * Get or create a container client.\r\n   * \r\n   * @param containerName - Name of the container\r\n   * @returns Container client\r\n   */\r\n  private async getContainerClient(containerName: string): Promise\u003cContainerClient\u003e {\r\n    const containerClient = this.blobServiceClient.getContainerClient(containerName);\r\n    \r\n    try {\r\n      // Create container if it doesn't exist\r\n      await containerClient.createIfNotExists({\r\n        access: 'blob'\r\n      });\r\n    } catch (error) {\r\n      throw new Error(`Failed to access container '${containerName}': ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n\r\n    return containerClient;\r\n  }\r\n\r\n  /**\r\n   * Upload data to blob storage with client-side encryption.\r\n   * \r\n   * @param containerName - Name of the container\r\n   * @param blobName - Name of the blob\r\n   * @param data - Data to encrypt and upload (string or Buffer)\r\n   * @returns Upload result with blob information\r\n   */\r\n  async uploadEncrypted(\r\n    containerName: string,\r\n    blobName: string,\r\n    data: string | Buffer\r\n  ): Promise\u003cUploadResult\u003e {\r\n    try {\r\n      // Convert string to Buffer if necessary\r\n      const plaintext = Buffer.isBuffer(data) ? data : Buffer.from(data, 'utf-8');\r\n\r\n      // Step 1: Encrypt data locally with envelope encryption\r\n      const encryptedData = await this.keyManager.encryptData(plaintext);\r\n\r\n      // Step 2: Get container client\r\n      const containerClient = await this.getContainerClient(containerName);\r\n      const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n\r\n      // Step 3: Upload encrypted data with metadata\r\n      const metadata = {\r\n        'encrypted': 'true',\r\n        'wrappedKey': encryptedData.wrappedKey.wrappedKey,\r\n        'keyId': encryptedData.wrappedKey.keyId,\r\n        'iv': encryptedData.iv,\r\n        'authTag': encryptedData.authTag,\r\n        'algorithm': 'aes-256-gcm'\r\n      };\r\n\r\n      await blockBlobClient.upload(\r\n        encryptedData.ciphertext,\r\n        encryptedData.ciphertext.length,\r\n        {\r\n          metadata\r\n        }\r\n      );\r\n\r\n      return {\r\n        blobName,\r\n        url: blockBlobClient.url,\r\n        wrappedKey: encryptedData.wrappedKey.wrappedKey,\r\n        keyId: encryptedData.wrappedKey.keyId\r\n      };\r\n    } catch (error) {\r\n      throw new Error(`Upload failed: ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Download and decrypt data from blob storage.\r\n   * \r\n   * @param containerName - Name of the container\r\n   * @param blobName - Name of the blob\r\n   * @returns Decrypted content and metadata\r\n   */\r\n  async downloadDecrypted(\r\n    containerName: string,\r\n    blobName: string\r\n  ): Promise\u003cDownloadResult\u003e {\r\n    try {\r\n      // Step 1: Get container and blob client\r\n      const containerClient = this.blobServiceClient.getContainerClient(containerName);\r\n      const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n\r\n      // Step 2: Check if blob exists\r\n      const exists = await blockBlobClient.exists();\r\n      if (!exists) {\r\n        throw new Error(`Blob '${blobName}' does not exist in container '${containerName}'`);\r\n      }\r\n\r\n      // Step 3: Download blob with metadata\r\n      const downloadResponse = await blockBlobClient.download();\r\n      \r\n      if (!downloadResponse.readableStreamBody) {\r\n        throw new Error('Failed to get blob content stream');\r\n      }\r\n\r\n      // Read stream to buffer\r\n      const ciphertext = await this.streamToBuffer(downloadResponse.readableStreamBody);\r\n      const metadata = downloadResponse.metadata || {};\r\n\r\n      // Step 4: Validate metadata\r\n      if (metadata.encrypted !== 'true') {\r\n        throw new Error('Blob is not encrypted or missing encryption metadata');\r\n      }\r\n\r\n      if (!metadata.wrappedKey || !metadata.keyId || !metadata.iv || !metadata.authTag) {\r\n        throw new Error('Blob is missing required encryption metadata');\r\n      }\r\n\r\n      // Step 5: Reconstruct encrypted data structure\r\n      const encryptedData: EncryptedData = {\r\n        ciphertext,\r\n        iv: metadata.iv,\r\n        authTag: metadata.authTag,\r\n        wrappedKey: {\r\n          wrappedKey: metadata.wrappedKey,\r\n          keyId: metadata.keyId\r\n        }\r\n      };\r\n\r\n      // Step 6: Decrypt data\r\n      const plaintext = await this.keyManager.decryptData(encryptedData);\r\n\r\n      return {\r\n        content: plaintext,\r\n        metadata\r\n      };\r\n    } catch (error) {\r\n      throw new Error(`Download failed: ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Helper method to convert a readable stream to a buffer.\r\n   * \r\n   * @param readableStream - Readable stream\r\n   * @returns Buffer with stream contents\r\n   */\r\n  private async streamToBuffer(readableStream: NodeJS.ReadableStream): Promise\u003cBuffer\u003e {\r\n    return new Promise((resolve, reject) =\u003e {\r\n      const chunks: Buffer[] = [];\r\n      readableStream.on('data', (chunk) =\u003e {\r\n        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));\r\n      });\r\n      readableStream.on('end', () =\u003e {\r\n        resolve(Buffer.concat(chunks));\r\n      });\r\n      readableStream.on('error', reject);\r\n    });\r\n  }\r\n\r\n  /**\r\n   * Delete a blob from storage.\r\n   * \r\n   * @param containerName - Name of the container\r\n   * @param blobName - Name of the blob\r\n   */\r\n  async deleteBlob(containerName: string, blobName: string): Promise\u003cvoid\u003e {\r\n    try {\r\n      const containerClient = this.blobServiceClient.getContainerClient(containerName);\r\n      const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n      await blockBlobClient.deleteIfExists();\r\n    } catch (error) {\r\n      throw new Error(`Delete failed: ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n  }\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { ConfigurationManager } from './config';\r\nimport { KeyManager } from './keyManager';\r\nimport { EncryptedBlobStorage } from './blobStorage';\r\n\r\n/**\r\n * Main demo script that demonstrates the full encrypt-upload-download-decrypt round-trip.\r\n */\r\nasync function main() {\r\n  console.log('=== Azure Encrypted Blob Storage Demo ===\\n');\r\n\r\n  try {\r\n    // Step 1: Initialize configuration\r\n    console.log('1. Initializing Azure clients...');\r\n    const configManager = new ConfigurationManager();\r\n    const config = configManager.getConfig();\r\n    console.log('✓ Configuration loaded\\n');\r\n\r\n    // Step 2: Initialize key manager and blob storage\r\n    console.log('2. Setting up encryption services...');\r\n    const keyManager = new KeyManager(\r\n      config.keyClient,\r\n      config.keyName,\r\n      config.credential,\r\n      config.keyVaultUrl\r\n    );\r\n    const blobStorage = new EncryptedBlobStorage(config.blobServiceClient, keyManager);\r\n    console.log('✓ Encryption services ready\\n');\r\n\r\n    // Step 3: Prepare test data\r\n    const containerName = 'encrypted-uploads';\r\n    const blobName = `test-${Date.now()}.txt`;\r\n    const sampleData = 'Hello, Azure! This is a secret message encrypted with envelope encryption using Key Vault and AES-256-GCM.';\r\n    \r\n    console.log('3. Test data prepared:');\r\n    console.log(`   Container: ${containerName}`);\r\n    console.log(`   Blob: ${blobName}`);\r\n    console.log(`   Content: \"${sampleData}\"\\n`);\r\n\r\n    // Step 4: Encrypt and upload\r\n    console.log('4. Encrypting and uploading...');\r\n    const uploadResult = await blobStorage.uploadEncrypted(\r\n      containerName,\r\n      blobName,\r\n      sampleData\r\n    );\r\n    \r\n    console.log('✓ Upload successful!');\r\n    console.log(`   Blob URL: ${uploadResult.url}`);\r\n    console.log(`   Key Vault Key ID: ${uploadResult.keyId}`);\r\n    console.log(`   Wrapped DEK (base64): ${uploadResult.wrappedKey.substring(0, 50)}...`);\r\n    console.log(`   Wrapped DEK Length: ${uploadResult.wrappedKey.length} characters\\n`);\r\n\r\n    // Step 5: Download and decrypt\r\n    console.log('5. Downloading and decrypting...');\r\n    const downloadResult = await blobStorage.downloadDecrypted(\r\n      containerName,\r\n      blobName\r\n    );\r\n    \r\n    const decryptedText = downloadResult.content.toString('utf-8');\r\n    console.log('✓ Download and decryption successful!');\r\n    console.log(`   Decrypted content: \"${decryptedText}\"\\n`);\r\n\r\n    // Step 6: Verify round-trip\r\n    console.log('6. Verifying round-trip...');\r\n    if (decryptedText === sampleData) {\r\n      console.log('✓ SUCCESS! Round-trip verified - original and decrypted data match.\\n');\r\n    } else {\r\n      console.error('✗ FAILURE! Data mismatch after round-trip.');\r\n      console.error(`   Original:  \"${sampleData}\"`);\r\n      console.error(`   Decrypted: \"${decryptedText}\"\\n`);\r\n      process.exit(1);\r\n    }\r\n\r\n    // Step 7: Metadata display\r\n    console.log('7. Encryption metadata stored in blob:');\r\n    console.log(`   Algorithm: ${downloadResult.metadata.algorithm}`);\r\n    console.log(`   IV (base64): ${downloadResult.metadata.iv}`);\r\n    console.log(`   Auth Tag (base64): ${downloadResult.metadata.authTag}`);\r\n    console.log(`   Key ID: ${downloadResult.metadata.keyId}\\n`);\r\n\r\n    // Step 8: Cleanup (optional)\r\n    console.log('8. Cleaning up...');\r\n    await blobStorage.deleteBlob(containerName, blobName);\r\n    console.log('✓ Test blob deleted\\n');\r\n\r\n    console.log('=== Demo completed successfully! ===');\r\n    console.log('\\nSecurity highlights:');\r\n    console.log('  • Data encryption key (DEK) generated locally');\r\n    console.log('  • DEK encrypted (wrapped) by Key Vault key');\r\n    console.log('  • Raw DEK never persisted or transmitted');\r\n    console.log('  • Key Vault key material never leaves Azure');\r\n    console.log('  • AES-256-GCM provides authenticated encryption');\r\n    console.log('  • All cryptographic parameters stored in blob metadata\\n');\r\n\r\n  } catch (error) {\r\n    console.error('\\n❌ Error occurred:');\r\n    console.error(error instanceof Error ? error.message : String(error));\r\n    console.error('\\nCommon issues:');\r\n    console.error('  • Ensure environment variables are set correctly');\r\n    console.error('  • Verify managed identity has permissions for Key Vault and Storage');\r\n    console.error('  • Check that the Key Vault key exists and is enabled');\r\n    console.error('  • Confirm network connectivity to Azure services\\n');\r\n    process.exit(1);\r\n  }\r\n}\r\n\r\n// Run the demo\r\nmain();\r\n\n```\n\n### src\\keyManager.ts\n```\nimport { KeyClient, CryptographyClient } from '@azure/keyvault-keys';\r\nimport { DefaultAzureCredential } from '@azure/identity';\r\nimport { createCipheriv, createDecipheriv, randomBytes } from 'crypto';\r\n\r\nexport interface WrappedKey {\r\n  wrappedKey: string; // Base64-encoded wrapped DEK\r\n  keyId: string; // Key Vault key ID used for wrapping\r\n}\r\n\r\nexport interface EncryptedData {\r\n  ciphertext: Buffer;\r\n  iv: string; // Base64-encoded initialization vector\r\n  authTag: string; // Base64-encoded authentication tag\r\n  wrappedKey: WrappedKey;\r\n}\r\n\r\n/**\r\n * Key management class that implements envelope encryption using Azure Key Vault.\r\n * \r\n * Envelope encryption pattern:\r\n * 1. Generate a Data Encryption Key (DEK) locally for each encryption operation\r\n * 2. Use Key Vault to wrap (encrypt) the DEK with the Key Encryption Key (KEK)\r\n * 3. Encrypt data locally with the DEK using AES-256-GCM\r\n * 4. Store the wrapped DEK alongside the encrypted data\r\n * 5. For decryption, unwrap the DEK using Key Vault, then decrypt locally\r\n * \r\n * Security guarantees:\r\n * - Raw DEK never persisted to disk or sent over the network\r\n * - KEK material never leaves Key Vault\r\n * - AES-GCM provides authenticated encryption\r\n */\r\nexport class KeyManager {\r\n  private readonly AES_KEY_SIZE = 32; // 256 bits\r\n  private readonly IV_SIZE = 12; // 96 bits for GCM\r\n  private readonly ALGORITHM = 'aes-256-gcm';\r\n  private cryptoClient: CryptographyClient | null = null;\r\n\r\n  constructor(\r\n    private readonly keyClient: KeyClient,\r\n    private readonly keyName: string,\r\n    private readonly credential: DefaultAzureCredential,\r\n    private readonly keyVaultUrl: string\r\n  ) {}\r\n\r\n  /**\r\n   * Get or create CryptographyClient for the key.\r\n   */\r\n  private async getCryptoClient(): Promise\u003cCryptographyClient\u003e {\r\n    if (!this.cryptoClient) {\r\n      const key = await this.keyClient.getKey(this.keyName);\r\n      if (!key.id) {\r\n        throw new Error('Key ID not found');\r\n      }\r\n      this.cryptoClient = new CryptographyClient(key.id, this.credential);\r\n    }\r\n    return this.cryptoClient;\r\n  }\r\n\r\n  /**\r\n   * Encrypt data using envelope encryption.\r\n   * \r\n   * @param plaintext - Data to encrypt\r\n   * @returns Encrypted data with wrapped DEK and cryptographic parameters\r\n   */\r\n  async encryptData(plaintext: Buffer): Promise\u003cEncryptedData\u003e {\r\n    // Step 1: Generate a random Data Encryption Key (DEK)\r\n    const dek = randomBytes(this.AES_KEY_SIZE);\r\n\r\n    // Step 2: Generate random initialization vector\r\n    const iv = randomBytes(this.IV_SIZE);\r\n\r\n    try {\r\n      // Step 3: Encrypt the plaintext locally using AES-256-GCM\r\n      const cipher = createCipheriv(this.ALGORITHM, dek, iv);\r\n      const ciphertext = Buffer.concat([\r\n        cipher.update(plaintext),\r\n        cipher.final()\r\n      ]);\r\n\r\n      // Get the authentication tag (separate from ciphertext in Node.js)\r\n      const authTag = cipher.getAuthTag();\r\n\r\n      // Step 4: Wrap (encrypt) the DEK using Key Vault's KEK\r\n      const wrappedKey = await this.wrapKey(dek);\r\n\r\n      // Zero out the DEK from memory (best effort)\r\n      dek.fill(0);\r\n\r\n      return {\r\n        ciphertext,\r\n        iv: iv.toString('base64'),\r\n        authTag: authTag.toString('base64'),\r\n        wrappedKey\r\n      };\r\n    } catch (error) {\r\n      // Ensure DEK is cleared even on error\r\n      dek.fill(0);\r\n      throw new Error(`Encryption failed: ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Decrypt data using envelope encryption.\r\n   * \r\n   * @param encryptedData - Encrypted data with wrapped DEK\r\n   * @returns Decrypted plaintext\r\n   */\r\n  async decryptData(encryptedData: EncryptedData): Promise\u003cBuffer\u003e {\r\n    let dek: Buffer | null = null;\r\n\r\n    try {\r\n      // Step 1: Unwrap (decrypt) the DEK using Key Vault\r\n      dek = await this.unwrapKey(encryptedData.wrappedKey);\r\n\r\n      // Step 2: Decrypt the ciphertext locally using the unwrapped DEK\r\n      const iv = Buffer.from(encryptedData.iv, 'base64');\r\n      const authTag = Buffer.from(encryptedData.authTag, 'base64');\r\n\r\n      const decipher = createDecipheriv(this.ALGORITHM, dek, iv);\r\n      decipher.setAuthTag(authTag);\r\n\r\n      const plaintext = Buffer.concat([\r\n        decipher.update(encryptedData.ciphertext),\r\n        decipher.final()\r\n      ]);\r\n\r\n      // Zero out the DEK from memory\r\n      dek.fill(0);\r\n\r\n      return plaintext;\r\n    } catch (error) {\r\n      // Ensure DEK is cleared even on error\r\n      if (dek) {\r\n        dek.fill(0);\r\n      }\r\n      throw new Error(`Decryption failed: ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Wrap (encrypt) a data encryption key using Key Vault.\r\n   * \r\n   * @param dek - Data encryption key to wrap\r\n   * @returns Wrapped key with key ID\r\n   */\r\n  private async wrapKey(dek: Buffer): Promise\u003cWrappedKey\u003e {\r\n    try {\r\n      const cryptoClient = await this.getCryptoClient();\r\n      const result = await cryptoClient.wrapKey('RSA-OAEP-256', dek);\r\n\r\n      if (!result.result) {\r\n        throw new Error('Key wrapping returned no result');\r\n      }\r\n\r\n      return {\r\n        wrappedKey: Buffer.from(result.result).toString('base64'),\r\n        keyId: result.keyID || ''\r\n      };\r\n    } catch (error) {\r\n      throw new Error(`Key wrapping failed: ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Unwrap (decrypt) a data encryption key using Key Vault.\r\n   * \r\n   * @param wrappedKey - Wrapped key to unwrap\r\n   * @returns Unwrapped data encryption key\r\n   */\r\n  private async unwrapKey(wrappedKey: WrappedKey): Promise\u003cBuffer\u003e {\r\n    try {\r\n      const wrappedKeyBytes = Buffer.from(wrappedKey.wrappedKey, 'base64');\r\n      const cryptoClient = await this.getCryptoClient();\r\n      \r\n      const result = await cryptoClient.unwrapKey('RSA-OAEP-256', wrappedKeyBytes);\r\n\r\n      if (!result.result) {\r\n        throw new Error('Key unwrapping returned no result');\r\n      }\r\n\r\n      return Buffer.from(result.result);\r\n    } catch (error) {\r\n      throw new Error(`Key unwrapping failed: ${error instanceof Error ? error.message : String(error)}`);\r\n    }\r\n  }\r\n}\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"./dist\",\r\n    \"rootDir\": \"./src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"moduleResolution\": \"node\",\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"sourceMap\": true\r\n  },\r\n  \"include\": [\"src/**/*\"],\r\n  \"exclude\": [\"node_modules\", \"dist\"]\r\n}\r\n\n```\n\n### ARCHITECTURE.md\n```\n# Architecture Diagram\r\n\r\n## System Components\r\n\r\n┌─────────────────────────────────────────────────────────────────────────────┐\r\n│                         Client Application (Node.js)                        │\r\n├─────────────────────────────────────────────────────────────────────────────┤\r\n│                                                                             │\r\n│  ┌─────────────────────────────────────────────────────────────────────┐   │\r\n│  │                    ConfigurationManager                            │   │\r\n│  │  • DefaultAzureCredential (Managed Identity)                      │   │\r\n│  │  • BlobServiceClient                                              │   │\r\n│  │  • KeyClient                                                      │   │\r\n│  └────────────────────┬───────────────────────┬────────────────────────┘   │\r\n│                       │                       │                            │\r\n│  ┌────────────────────▼──────────────┐   ┌───▼────────────────────────┐   │\r\n│  │       KeyManager                  │   │  EncryptedBlobStorage      │   │\r\n│  │  • Envelope Encryption            │◄──┤  • Upload/Download         │   │\r\n│  │  • AES-256-GCM                    │   │  • Stream Handling         │   │\r\n│  │  • DEK Generation                 │   │  • Metadata Management     │   │\r\n│  │  • Wrap/Unwrap via Key Vault      │   └────────────────────────────┘   │\r\n│  └────────────────────┬──────────────┘                                     │\r\n│                       │                                                     │\r\n└───────────────────────┼─────────────────────────────────────────────────────┘\r\n                        │\r\n        ┌───────────────┴────────────────┐\r\n        │                                │\r\n        ▼                                ▼\r\n┌────────────────────┐         ┌──────────────────────┐\r\n│  Azure Key Vault   │         │  Azure Blob Storage  │\r\n├────────────────────┤         ├──────────────────────┤\r\n│                    │         │                      │\r\n│  Key Encryption    │         │  Container           │\r\n│  Key (KEK)         │         │    └─ Encrypted Blob │\r\n│                    │         │         ├─ Ciphertext│\r\n│  • RSA-OAEP-256    │         │         └─ Metadata: │\r\n│  • Wrap DEK        │         │            • Wrapped │\r\n│  • Unwrap DEK      │         │              DEK     │\r\n│                    │         │            • IV      │\r\n│  KEK never leaves  │         │            • AuthTag │\r\n│  Key Vault         │         │            • Key ID  │\r\n└────────────────────┘         └──────────────────────┘\r\n\r\n\r\n## Encryption Flow (Upload)\r\n\r\n┌──────────────┐\r\n│  Plaintext   │\r\n└──────┬───────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  1. Generate DEK (256-bit)       │\r\n│     randomBytes(32)              │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  2. Encrypt Data Locally         │\r\n│     AES-256-GCM                  │\r\n│     plaintext + DEK + IV         │\r\n│     → ciphertext + authTag       │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  3. Wrap DEK with Key Vault      │\r\n│     KeyVault.wrapKey()           │\r\n│     DEK + KEK → Wrapped DEK      │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  4. Erase DEK from Memory        │\r\n│     dek.fill(0)                  │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  5. Upload to Blob Storage       │\r\n│     Data: ciphertext             │\r\n│     Metadata:                    │\r\n│       - wrappedKey               │\r\n│       - iv                       │\r\n│       - authTag                  │\r\n│       - keyId                    │\r\n└──────────────────────────────────┘\r\n\r\n\r\n## Decryption Flow (Download)\r\n\r\n┌──────────────────────────────────┐\r\n│  1. Download from Blob Storage   │\r\n│     Get: ciphertext + metadata   │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  2. Unwrap DEK with Key Vault    │\r\n│     KeyVault.unwrapKey()         │\r\n│     Wrapped DEK + KEK → DEK      │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  3. Decrypt Data Locally         │\r\n│     AES-256-GCM                  │\r\n│     ciphertext + DEK + IV        │\r\n│     → plaintext                  │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  4. Verify Auth Tag              │\r\n│     GCM authentication           │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────────────────────────┐\r\n│  5. Erase DEK from Memory        │\r\n│     dek.fill(0)                  │\r\n└──────┬───────────────────────────┘\r\n       │\r\n       ▼\r\n┌──────────────┐\r\n│  Plaintext   │\r\n└──────────────┘\r\n\r\n\r\n## Security Layers\r\n\r\nLayer 1: Physical Security\r\n  └─ Azure Data Centers (ISO 27001, SOC 2)\r\n\r\nLayer 2: Network Security\r\n  └─ HTTPS/TLS for all Azure API calls\r\n\r\nLayer 3: Authentication\r\n  └─ Managed Identity / Azure AD\r\n\r\nLayer 4: Authorization\r\n  └─ Azure RBAC\r\n      ├─ Key Vault Crypto User (wrap/unwrap only)\r\n      └─ Storage Blob Data Contributor\r\n\r\nLayer 5: Key Management\r\n  └─ Azure Key Vault\r\n      ├─ KEK stored in HSM (optional)\r\n      ├─ Key rotation support\r\n      └─ Audit logging\r\n\r\nLayer 6: Data Encryption\r\n  └─ Client-Side Encryption\r\n      ├─ AES-256-GCM (authenticated encryption)\r\n      ├─ Unique DEK per blob\r\n      ├─ Random IV per encryption\r\n      └─ DEK never persisted\r\n\r\n\r\n## Key Hierarchy\r\n\r\n┌─────────────────────────────────────┐\r\n│   Master Key (Azure Key Vault)      │  ◄── Managed by Azure\r\n│   • RSA 2048/3072/4096              │      (can be HSM-backed)\r\n│   • Never leaves Key Vault          │\r\n│   • Used for wrap/unwrap only       │\r\n└────────────┬────────────────────────┘\r\n             │\r\n             │ wraps/unwraps\r\n             │\r\n┌────────────▼────────────────────────┐\r\n│   Data Encryption Key (DEK)         │  ◄── Generated per upload\r\n│   • AES-256 (32 bytes)              │      Exists only in memory\r\n│   • Random per blob                 │      Erased after use\r\n│   • Never stored raw                │\r\n└────────────┬────────────────────────┘\r\n             │\r\n             │ encrypts/decrypts\r\n             │\r\n┌────────────▼────────────────────────┐\r\n│   Actual Data (Plaintext)           │\r\n│   • Your sensitive content          │\r\n│   • Files, strings, buffers         │\r\n└─────────────────────────────────────┘\r\n\r\n\r\n## Data Flow Summary\r\n\r\nWRITE PATH:\r\n  User Data → [Local AES-256-GCM] → Ciphertext\r\n           ↘\r\n            Random DEK → [Key Vault Wrap] → Wrapped DEK\r\n                                              ↓\r\n                          Blob Storage ← [Ciphertext + Wrapped DEK]\r\n\r\nREAD PATH:\r\n  Blob Storage → [Ciphertext + Wrapped DEK]\r\n                                ↓\r\n                   Wrapped DEK → [Key Vault Unwrap] → DEK\r\n                                                        ↓\r\n                                   Ciphertext → [Local AES-256-GCM] → User Data\r\n\r\n\r\n## Components Interaction Matrix\r\n\r\n                    │ KeyManager │ BlobStorage │ Key Vault │ Blob Storage\r\n────────────────────┼────────────┼─────────────┼───────────┼──────────────\r\nConfigManager       │   Creates  │   Creates   │  Connects │  Connects\r\nKeyManager          │     -      │   Used by   │  Wrap/    │     -\r\n                    │            │             │  Unwrap   │\r\nEncryptedBlobStorage│   Uses     │     -       │     -     │  Upload/\r\n                    │            │             │           │  Download\r\nUser Application    │   Uses     │   Uses      │     -     │     -\r\n\r\n\r\n## File Organization\r\n\r\nsrc/\r\n├── config.ts          → Manages Azure connections\r\n│   └── ConfigurationManager\r\n│       ├── credential: DefaultAzureCredential\r\n│       ├── blobServiceClient: BlobServiceClient\r\n│       └── keyClient: KeyClient\r\n│\r\n├── keyManager.ts      → Handles envelope encryption\r\n│   └── KeyManager\r\n│       ├── encryptData()   → plaintext → EncryptedData\r\n│       ├── decryptData()   → EncryptedData → plaintext\r\n│       ├── wrapKey()       → DEK → Wrapped DEK\r\n│       └── unwrapKey()     → Wrapped DEK → DEK\r\n│\r\n├── blobStorage.ts     → Manages encrypted blob operations\r\n│   └── EncryptedBlobStorage\r\n│       ├── uploadEncrypted()     → data → blob\r\n│       ├── downloadDecrypted()   → blob → data\r\n│       ├── deleteBlob()\r\n│       └── streamToBuffer()\r\n│\r\n└── index.ts           → Demo application\r\n    └── main()\r\n        ├── Initialize services\r\n        ├── Upload encrypted blob\r\n        ├── Download and decrypt\r\n        └── Verify round-trip\r\n\r\n\r\n## Environment Variables\r\n\r\n┌───────────────────────────────────┐\r\n│  AZURE_STORAGE_ACCOUNT_NAME       │ → Blob Service URL\r\n│  AZURE_KEY_VAULT_URL              │ → Key Client\r\n│  AZURE_KEY_VAULT_KEY_NAME         │ → Specific Key\r\n└───────────────────────────────────┘\r\n            │\r\n            ▼\r\n┌───────────────────────────────────┐\r\n│  DefaultAzureCredential           │\r\n│  • Managed Identity               │\r\n│  • Azure CLI (local dev)          │\r\n│  • Environment variables          │\r\n│  • Visual Studio                  │\r\n└───────────────────────────────────┘\r\n\n```\n\n### QUICKSTART.md\n```\n# Quick Start Guide\r\n\r\n## Overview\r\n\r\nThis project implements client-side encryption for Azure Blob Storage using envelope encryption with Azure Key Vault.\r\n\r\n## Architecture\r\n\r\n### Envelope Encryption Pattern\r\n\r\n```\r\nUpload:\r\n1. Generate DEK (256-bit AES key) locally\r\n2. Encrypt data with DEK using AES-256-GCM → Ciphertext + IV + Auth Tag\r\n3. Wrap DEK with KEK in Key Vault → Wrapped DEK\r\n4. Upload ciphertext to Blob Storage\r\n5. Store metadata: Wrapped DEK, IV, Auth Tag, Key ID\r\n6. Erase DEK from memory\r\n\r\nDownload:\r\n1. Download ciphertext and metadata\r\n2. Unwrap DEK using Key Vault\r\n3. Decrypt ciphertext with DEK\r\n4. Erase DEK from memory\r\n```\r\n\r\n## Project Structure\r\n\r\n```\r\n├── src/\r\n│   ├── config.ts         - Azure client configuration\r\n│   ├── keyManager.ts     - Key Vault integration \u0026 envelope encryption\r\n│   ├── blobStorage.ts    - Encrypted blob upload/download\r\n│   └── index.ts          - Demo application\r\n├── package.json\r\n├── tsconfig.json\r\n├── .env.example\r\n└── README.md\r\n```\r\n\r\n## Setup Instructions\r\n\r\n### 1. Install Dependencies\r\n\r\n```bash\r\nnpm install\r\n```\r\n\r\n### 2. Create Azure Resources\r\n\r\n```bash\r\n# Resource group\r\naz group create --name rg-encrypted-storage --location eastus\r\n\r\n# Storage account\r\naz storage account create \\\r\n  --name \u003cyour-storage-account\u003e \\\r\n  --resource-group rg-encrypted-storage \\\r\n  --sku Standard_LRS\r\n\r\n# Key Vault\r\naz keyvault create \\\r\n  --name \u003cyour-keyvault\u003e \\\r\n  --resource-group rg-encrypted-storage \\\r\n  --location eastus\r\n\r\n# Create encryption key\r\naz keyvault key create \\\r\n  --vault-name \u003cyour-keyvault\u003e \\\r\n  --name encryption-key \\\r\n  --kty RSA \\\r\n  --size 2048\r\n```\r\n\r\n### 3. Configure Environment\r\n\r\nCopy `.env.example` to `.env`:\r\n\r\n```bash\r\nAZURE_STORAGE_ACCOUNT_NAME=\u003cyour-storage-account\u003e\r\nAZURE_KEY_VAULT_URL=https://\u003cyour-keyvault\u003e.vault.azure.net/\r\nAZURE_KEY_VAULT_KEY_NAME=encryption-key\r\n```\r\n\r\n### 4. Assign Permissions\r\n\r\n```bash\r\nUSER_PRINCIPAL_ID=$(az ad signed-in-user show --query id -o tsv)\r\n\r\n# Storage Blob Data Contributor\r\naz role assignment create \\\r\n  --assignee $USER_PRINCIPAL_ID \\\r\n  --role \"Storage Blob Data Contributor\" \\\r\n  --scope /subscriptions/\u003csubscription-id\u003e/resourceGroups/rg-encrypted-storage/providers/Microsoft.Storage/storageAccounts/\u003cyour-storage-account\u003e\r\n\r\n# Key Vault Crypto User\r\naz role assignment create \\\r\n  --assignee $USER_PRINCIPAL_ID \\\r\n  --role \"Key Vault Crypto User\" \\\r\n  --scope /subscriptions/\u003csubscription-id\u003e/resourceGroups/rg-encrypted-storage/providers/Microsoft.KeyVault/vaults/\u003cyour-keyvault\u003e\r\n```\r\n\r\n### 5. Authenticate\r\n\r\n```bash\r\naz login\r\n```\r\n\r\n### 6. Run the Demo\r\n\r\n```bash\r\n# Build\r\nnpm run build\r\n\r\n# Run\r\nnpm start\r\n\r\n# Or with ts-node\r\nnpm run dev\r\n```\r\n\r\n## Usage Examples\r\n\r\n### Basic Upload/Download\r\n\r\n```typescript\r\nimport { ConfigurationManager } from './config';\r\nimport { KeyManager } from './keyManager';\r\nimport { EncryptedBlobStorage } from './blobStorage';\r\n\r\n// Initialize\r\nconst configManager = new ConfigurationManager();\r\nconst config = configManager.getConfig();\r\nconst keyManager = new KeyManager(\r\n  config.keyClient,\r\n  config.keyName,\r\n  config.credential,\r\n  config.keyVaultUrl\r\n);\r\nconst storage = new EncryptedBlobStorage(config.blobServiceClient, keyManager);\r\n\r\n// Upload encrypted\r\nconst result = await storage.uploadEncrypted(\r\n  'my-container',\r\n  'secret.txt',\r\n  'Confidential data'\r\n);\r\n\r\nconsole.log(`Uploaded to: ${result.url}`);\r\nconsole.log(`Key ID: ${result.keyId}`);\r\nconsole.log(`Wrapped DEK: ${result.wrappedKey}`);\r\n\r\n// Download and decrypt\r\nconst download = await storage.downloadDecrypted('my-container', 'secret.txt');\r\nconst plaintext = download.content.toString('utf-8');\r\nconsole.log(`Decrypted: ${plaintext}`);\r\n\r\n// Clean up\r\nawait storage.deleteBlob('my-container', 'secret.txt');\r\n```\r\n\r\n### Direct Encryption (without storage)\r\n\r\n```typescript\r\nimport { KeyManager } from './keyManager';\r\n\r\nconst keyManager = new KeyManager(keyClient, keyName, credential, keyVaultUrl);\r\n\r\n// Encrypt\r\nconst plaintext = Buffer.from('Secret message', 'utf-8');\r\nconst encrypted = await keyManager.encryptData(plaintext);\r\n\r\nconsole.log('Ciphertext:', encrypted.ciphertext.toString('base64'));\r\nconsole.log('IV:', encrypted.iv);\r\nconsole.log('Auth Tag:', encrypted.authTag);\r\nconsole.log('Wrapped DEK:', encrypted.wrappedKey.wrappedKey);\r\n\r\n// Decrypt\r\nconst decrypted = await keyManager.decryptData(encrypted);\r\nconsole.log('Plaintext:', decrypted.toString('utf-8'));\r\n```\r\n\r\n## Security Features\r\n\r\n✓ **Local Encryption** - Data encrypted with AES-256-GCM before leaving your system\r\n✓ **Envelope Encryption** - DEK wrapped by Key Vault KEK\r\n✓ **No Key Persistence** - Raw DEKs erased from memory after use\r\n✓ **KEK Protection** - Key material never leaves Key Vault\r\n✓ **Authenticated Encryption** - GCM mode provides integrity verification\r\n✓ **Unique Keys** - Each upload gets a fresh DEK\r\n✓ **Metadata Storage** - All parameters stored securely in blob metadata\r\n\r\n## What's Stored Where\r\n\r\n### Blob Storage (Encrypted)\r\n- Ciphertext (encrypted data)\r\n\r\n### Blob Metadata (Unencrypted but Safe)\r\n- Wrapped DEK (can only be unwrapped by authorized Key Vault access)\r\n- Initialization Vector (IV)\r\n- Authentication Tag\r\n- Key Vault Key ID\r\n- Algorithm identifier\r\n\r\n### Key Vault\r\n- Key Encryption Key (KEK) - never leaves Key Vault\r\n- Wrap/unwrap operations performed within Key Vault\r\n\r\n### Memory (Temporary)\r\n- Data Encryption Key (DEK) - erased immediately after use\r\n\r\n## Common Issues\r\n\r\n### Authentication Errors\r\n- Ensure you're logged in: `az login`\r\n- Verify you have the correct roles assigned\r\n\r\n### Key Vault Access Denied\r\n- Check that Key Vault key exists and is enabled\r\n- Verify \"Key Vault Crypto User\" role is assigned\r\n- Ensure Key Vault has RBAC authorization mode (not access policies)\r\n\r\n### Storage Access Denied\r\n- Verify \"Storage Blob Data Contributor\" role is assigned\r\n- Check that storage account name is correct\r\n\r\n### Environment Variables Not Found\r\n- Copy `.env.example` to `.env` and configure\r\n- Load environment variables before running\r\n\r\n## Performance Notes\r\n\r\n- Encryption/decryption is CPU-bound (happens locally)\r\n- Key wrap/unwrap adds ~100-200ms per operation\r\n- Network transfer time depends on blob size\r\n- Consider caching CryptographyClient for repeated operations\r\n\r\n## Production Considerations\r\n\r\n1. **Key Rotation**: Store key ID in metadata to support multiple key versions\r\n2. **Monitoring**: Enable Azure Monitor for Key Vault operations\r\n3. **Managed Identity**: Use system/user-assigned identity in Azure environments\r\n4. **Key Size**: Consider RSA 3072 or 4096 for enhanced security\r\n5. **HSM**: Use Azure Key Vault Managed HSM for FIPS 140-2 Level 3 compliance\r\n6. **Soft Delete**: Enable Key Vault soft delete and purge protection\r\n7. **Access Control**: Use Azure RBAC for fin